// Guard + flatten + classify the incoming message for routing.
//
// body: { locale, org_prompt, message: { direction, body, media_type,
//         media_base64, media_mime, sent_at }, contact, detect_*, thread[] }
const SECRET = '__N8N_WEBHOOK_SECRET__';

const item = $input.first().json;
if ((item.headers ?? {})['x-sanayed-secret'] !== SECRET) {
  throw new Error('unauthorized');
}

const body = item.body ?? item;
const msg = body.message ?? {};
const mime = String(msg.media_mime ?? '');
const hasMedia = Boolean(msg.media_base64);

let kind = 'text';
if (hasMedia && mime.startsWith('image/')) kind = 'image';
else if (hasMedia && mime.startsWith('audio/')) kind = 'audio';

// The manager's app language governs every field the model writes. It arrives
// explicitly because media carries no text to infer a language from: an image
// or a voice note used to be judged in whatever language the model felt like,
// which for an Arabic manager meant English. Default matches orgs.locale.
const locale = body.locale === 'en' ? 'en' : 'ar';

return [{
  json: {
    kind,
    locale,
    org_prompt: body.org_prompt ?? null,
    contact: body.contact ?? {},
    detect_unauthorized_promise: body.detect_unauthorized_promise,
    detect_off_channel: body.detect_off_channel,
    message: { direction: msg.direction, body: msg.body, media_type: msg.media_type, sent_at: msg.sent_at },
    thread: Array.isArray(body.thread) ? body.thread : [],
    media_base64: hasMedia ? String(msg.media_base64) : '',
    media_mime: mime,
  },
}];

// Assemble the judge request. Reached three ways:
//   text  -> straight from Prepare
//   image -> straight from Prepare (the judge model sees the image itself)
//   audio -> via Whisper, $json.text is the transcription
const prep = $('Prepare').first().json;
const cur = $input.first().json;

const kind = prep.kind;
const transcript = kind === 'audio' ? String(cur.text ?? '').trim() : '';

// The manager's app language. Whisper is deliberately NOT told which language
// to expect — it transcribes what was actually spoken — so for audio the
// verbatim text may be in a different language from everything below it.
const locale = prep.locale === 'en' ? 'en' : 'ar';
const langName = locale === 'en' ? 'English' : 'Arabic';

const agent = prep.contact?.agent_name || 'the agent';
const client = prep.contact?.display_name || 'the client';

const lines = (prep.thread ?? []).map((m) => {
  const who = m.direction === 'in' ? 'Client' : 'Agent';
  const text = m.transcript || m.body || ('[' + (m.media_type || 'message') + ']');
  return who + ': ' + text;
});

const orgPrompt = prep.org_prompt ||
  'You review WhatsApp conversations between staff and clients. Alert the manager when a staff member promises something the company may not honour, moves the client off the official channel, or when the client is angry, threatening to leave, or asking for a manager.';

const disabled = [];
if (prep.detect_unauthorized_promise === false) disabled.push('unauthorized_promise');
if (prep.detect_off_channel === false) disabled.push('off_channel');

// Fields the model writes that must land in the manager's language. Listing
// them by name beats a general instruction: the earlier "same language as the
// conversation" wording left media analysis with nothing to infer from.
const written = ['title', 'insight', 'recommended_action'];
if (kind === 'image') written.push('media_description');
if (kind === 'audio') written.push('transcript_translation');

const system = orgPrompt + `

---
OUTPUT CONTRACT (mandatory, overrides anything above about formatting)

You are judging whether the SALES MANAGER must personally intervene in this conversation. Most messages need nothing: when in doubt, do not alert — a false alarm costs more than a miss, because a noisy feed stops being read.

Do NOT alert for slow replies or silence; those are measured precisely elsewhere.${disabled.length ? '\nNEVER use these types (disabled by the manager): ' + disabled.join(', ') + '.' : ''}

OUTPUT LANGUAGE
Write these fields in ${langName}: ${written.join(', ')}.
${langName} is the manager's app language. It does NOT depend on the language of the conversation — write ${langName} even when the client and the agent are speaking something else, and even when the message you are judging has no text at all.

The ONE exception is "evidence.quote": copy the triggering words verbatim, in the language they were actually written or spoken in. Never translate, tidy or shorten a quote — it is evidence, and the manager checks it against the real chat.

Name the people: the agent is "${agent}", the client is "${client}"${prep.contact?.is_vip ? ' (VIP client)' : ''}.

RESPOND ONLY WITH JSON:
{
  "needs_attention": false,
  "type": "unauthorized_promise" | "off_channel" | "escalation" | "other",
  "severity": "urgent" | "high" | "medium" | "low",
  "title": "short headline naming who did what",
  "insight": "one or two sentences the manager can act on",
  "recommended_action": "the single next step",
  "evidence": { "quote": "the exact words that triggered this, copied verbatim" },
  "media_description": "",
  "transcript_translation": ""
}
${kind === 'image' ? '\n"media_description" is REQUIRED here: one factual sentence in ' + langName + ' describing what the attached image shows, including any text visible in it — even when needs_attention is false. If the image contains text in another language, render its meaning inside your ' + langName + ' sentence. Leave "transcript_translation" empty.' : ''}${kind === 'audio' ? '\nThe voice note above was transcribed verbatim, in whatever language the speaker actually used. If that is not ' + langName + ', put a faithful ' + langName + ' translation of the whole transcription in "transcript_translation" — the manager may not read the spoken language. If it is already ' + langName + ', leave "transcript_translation" empty. Never edit or replace the verbatim transcription itself. Leave "media_description" empty.' : ''}${kind === 'text' ? '\nLeave "media_description" and "transcript_translation" empty.' : ''}

If nothing requires the manager, return needs_attention: false and leave the alert fields empty${kind === 'image' ? ' — but still fill "media_description"' : ''}${kind === 'audio' ? ' — but still fill "transcript_translation" if a translation is needed' : ''}.`;

const newestWho = prep.message?.direction === 'in' ? 'Client' : 'Agent';
let newest;
if (kind === 'audio') {
  newest = newestWho + ' (voice note, transcribed verbatim in the language spoken): ' + (transcript || '[unintelligible]');
} else if (kind === 'image') {
  newest = newestWho + ' sent the attached image' + (prep.message?.body ? ' with caption: ' + prep.message.body : '') + '.';
} else {
  newest = newestWho + ': ' + (prep.message?.body || '[' + (prep.message?.media_type || 'message') + ']');
}

const userText = 'Conversation (oldest first):\n' + lines.join('\n').slice(-6000) +
  '\n\nNewest message (the one to judge, in context): ' + newest;

const userContent = kind === 'image'
  ? [
      { type: 'text', text: userText },
      { type: 'image_url', image_url: { url: 'data:' + prep.media_mime + ';base64,' + prep.media_base64 } },
    ]
  : userText;

return [{
  json: {
    kind,
    locale,
    transcript,
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: userContent },
    ],
  },
}];

// Parse + clamp the verdict, and attach the media transcript/description the
// app stores on the message row.
const built = $('Build messages').first().json;
const raw = $input.first().json;
const content = raw?.choices?.[0]?.message?.content ?? '';

const locale = built.locale === 'en' ? 'en' : 'ar';
// Labels the manager reads, so they follow the manager's language too.
const TRANSLATION_LABEL = { ar: 'الترجمة', en: 'Translation' };

// A voice note is stored verbatim in the language it was spoken, because
// evidence has to survive; the translation is appended beneath it so an
// Arabic-only manager can still read an English client. Same field, because
// messages.transcript is what the app renders for a voice note.
function composeTranscript(parsed) {
  if (built.kind === 'audio') {
    const verbatim = String(built.transcript || '').trim();
    const translated = String(parsed.transcript_translation ?? '').trim().slice(0, 2000);
    if (!verbatim) return '';
    if (!translated || translated === verbatim) return verbatim;
    return verbatim + '\n\n' + TRANSLATION_LABEL[locale] + ': ' + translated;
  }
  return String(parsed.media_description ?? '').slice(0, 2000);
}

let parsed;
try {
  parsed = JSON.parse(content);
} catch (e) {
  const start = content.indexOf('{');
  const end = content.lastIndexOf('}');
  if (start === -1 || end <= start) {
    // Unparseable: keep the verbatim transcription anyway, it cost a Whisper
    // call and is still worth storing as thread context.
    return [{ json: { needs_attention: false, transcript: String(built.transcript || '') } }];
  }
  parsed = JSON.parse(content.slice(start, end + 1));
}

const TYPES = ['unauthorized_promise', 'off_channel', 'escalation', 'other'];
const SEVERITIES = ['urgent', 'high', 'medium', 'low'];

return [{
  json: {
    needs_attention: parsed.needs_attention === true,
    type: TYPES.includes(parsed.type) ? parsed.type : 'other',
    severity: SEVERITIES.includes(parsed.severity) ? parsed.severity : 'medium',
    title: String(parsed.title ?? '').slice(0, 300),
    insight: String(parsed.insight ?? '').slice(0, 2000),
    recommended_action: String(parsed.recommended_action ?? '').slice(0, 1000),
    evidence: typeof parsed.evidence === 'object' && parsed.evidence !== null ? parsed.evidence : {},
    transcript: composeTranscript(parsed),
  },
}];
